"""
Test to verify that models inheriting explicit primary keys don't get W042 warning.
This tests the fix for the issue described in the PR where models.W042 is raised
on inherited manually specified primary keys.
"""
from unittest import mock

from django.core import checks
from django.core.checks import Warning
from django.db import models
from django.test import SimpleTestCase
from django.test.utils import isolate_apps, override_settings, override_system_checks


def mocked_is_overridden(self, setting):
    # Force treating DEFAULT_AUTO_FIELD = 'django.db.models.AutoField' as a not
    # overridden setting.
    return (
        setting != 'DEFAULT_AUTO_FIELD' or
        self.DEFAULT_AUTO_FIELD != 'django.db.models.AutoField'
    )


@mock.patch('django.conf.UserSettingsHolder.is_overridden', mocked_is_overridden)
@override_settings(DEFAULT_AUTO_FIELD='django.db.models.AutoField')
@isolate_apps('check_framework.apps.CheckDefaultPKConfig', attr_name='apps')
@override_system_checks([checks.model_checks.check_all_models])
class InheritedPrimaryKeyTests(SimpleTestCase):

    def test_inherited_explicit_pk(self):
        """Child models inheriting explicit pk should NOT get W042 warning."""

        class Parent(models.Model):
            id = models.BigAutoField(primary_key=True)

        class Child(Parent):
            pass

        # Run checks
        result = checks.run_checks(app_configs=self.apps.get_app_configs())

        # Neither Parent nor Child should get the warning
        self.assertEqual(result, [])

    def test_multilevel_inherited_explicit_pk(self):
        """Multi-level inheritance with explicit pk at root should NOT get W042 warning."""

        class GrandParent(models.Model):
            id = models.BigAutoField(primary_key=True)

        class Parent(GrandParent):
            pass

        class Child(Parent):
            pass

        # Run checks
        result = checks.run_checks(app_configs=self.apps.get_app_configs())

        # None should get the warning
        self.assertEqual(result, [])

    def test_inherited_auto_pk_still_warns(self):
        """Child models inheriting auto-created pk SHOULD still get W042 warning."""

        class Parent(models.Model):
            pass  # Auto-created pk

        class Child(Parent):
            pass

        # Run checks
        result = checks.run_checks(app_configs=self.apps.get_app_configs())

        # Both Parent and Child should get the warning
        self.assertEqual(len(result), 2)
        self.assertEqual(result[0].id, 'models.W042')
        self.assertEqual(result[1].id, 'models.W042')
